// FASE 2 — nó "WhatsApp: separar mensagem" (logo depois do WhatsApp Trigger).
// Pega a mensagem que chegou da Meta e separa: quem mandou, texto, ID da mídia e
// o número do bot que recebeu (para responder pelo mesmo número).
// Avisos de "entregue/lido" (statuses) não são mensagens: o fluxo para aqui.
const v = $input.first().json || {};
const valor = v.value || v; // o WhatsApp Trigger às vezes entrega dentro de "value"
const m = (valor.messages || [])[0];
if (!m) return []; // não é mensagem nova (ex.: status de entrega)

// Celulares do Brasil: às vezes a Meta entrega o número sem o 9 (55 + DDD + 8 dígitos).
// Para responder, colocamos o 9 de volta; senão o envio é recusado.
let para = String(m.from || '');
if (/^55\d{10}$/.test(para) && /[6-9]/.test(para[4])) para = para.slice(0, 4) + '9' + para.slice(4);

const tipo = m.type; // text | image | audio | document | ...
const doc = m.document || {};
const ehPdf = tipo === 'document' && (doc.mime_type || '').toLowerCase().startsWith('application/pdf');
return [{
  json: {
    para, // telefone: fica só na memória desta execução; no banco vira hash
    id_bruto: 'wa:' + para,
    phone_number_id: (valor.metadata || {}).phone_number_id,
    tipo,
    texto: tipo === 'text' ? ((m.text || {}).body || '') : ((m.image || {}).caption || (m.document || {}).caption || ''),
    // Fotos, PDFs e áudios são baixados (outros arquivos recebem resposta pronta, sem download)
    media_id: (m.image || {}).id || (ehPdf ? doc.id : null) || (m.audio || {}).id || null,
    media_mime: (m.image || {}).mime_type || (ehPdf ? doc.mime_type : null) || (m.audio || {}).mime_type || null,
    eh_pdf: ehPdf,
  },
}];

// FASE 2 — nó "Preparar áudio" (só para mensagens de voz).
// O serviço de transcrição descobre o formato pela extensão do arquivo, e o arquivo
// que a Meta entrega pode vir sem nome. Aqui damos um nome com a extensão certa.
// Só chega aqui quem já respondeu SIM ao consentimento.
// O áudio fica só na memória desta execução; nada é salvo.
const baixado = $('Meta: baixar mídia').first();
const item = { json: {}, binary: baixado.binary || {} };
const b = item.binary.data;
if (b) {
  const sep = $('WhatsApp: separar mensagem').first().json;
  const mime = ((b.mimeType || sep.media_mime || '') + '').toLowerCase().split(';')[0].trim();
  const ext = {
    'audio/ogg': 'ogg', 'audio/opus': 'ogg', 'audio/mpeg': 'mp3', 'audio/mp3': 'mp3',
    'audio/mp4': 'm4a', 'audio/aac': 'm4a', 'audio/x-m4a': 'm4a', 'audio/webm': 'webm',
    'audio/wav': 'wav', 'audio/x-wav': 'wav', 'audio/amr': 'amr',
  }[mime] || 'ogg';
  b.fileName = 'audio.' + ext;
}
return [item];

// FASE 2 — nó "Entrada → formato padrão" do fluxo do WhatsApp.
// ATENÇÃO: o nó precisa ter o nome EXATO "Entrada → formato padrão",
// porque o nó "Decidir rota" lê os dados por esse nome.
//
// Recebe a saída do nó "Meta: baixar mídia" (quando houve foto ou PDF), do
// "Transcrever áudio (Groq)" (quando foi áudio) ou direto do "Tem mídia?" (só texto).
const sep = $('WhatsApp: separar mensagem').first().json;
const item = $input.first();

let imagem_base64 = null, imagem_mime = null, imagem_bytes = 0;
const chave = Object.keys(item.binary || {})[0];

if ((sep.tipo === 'image' || sep.eh_pdf) && chave) {
  const buf = await this.helpers.getBinaryDataBuffer(0, chave);
  const mime = ((sep.media_mime || item.binary[chave].mimeType || '') + '').toLowerCase().split(';')[0].trim();
  imagem_base64 = buf.toString('base64');
  imagem_mime = mime === 'image/jpg' ? 'image/jpeg' : mime;
  imagem_bytes = buf.length;
}

// Áudio: o texto falado vira a mensagem, como se a pessoa tivesse digitado.
// Se a transcrição falhar (ou vier vazia), o Zé pede para mandar de outro jeito.
// Quem ainda não respondeu SIM não tem o áudio transcrito (o Zé só pede o consentimento).
let texto = (sep.texto || '').toString().trim();
let tem_audio = false;
if (sep.tipo === 'audio') {
  let falado = '';
  try { falado = ((($('Transcrever áudio (Groq)').first() || {}).json || {}).text || '').toString().trim(); } catch (e) { falado = ''; }
  // O Whisper às vezes "inventa" legendas quando o áudio é silêncio ou ruído
  if (/amara\.org|legendas? (pela|por)|obrigad[oa] por assistir|inscreva-se/i.test(falado)) falado = '';
  if (falado) texto = falado.slice(0, 1000); else tem_audio = true;
}

return [{
  json: {
    canal: 'whatsapp',
    id_bruto: sep.id_bruto, // o 9 dos celulares já foi corrigido no "WhatsApp: separar mensagem"
    para: sep.para, // usado SÓ pelo nó de saída para responder; nunca é salvo
    texto,
    imagem_base64, imagem_mime, imagem_bytes,
    tem_audio, // true só quando o áudio não pôde ser entendido
    outro_arquivo: !['text', 'image', 'audio'].includes(sep.tipo) && !sep.eh_pdf,
  },
}];

// ===== Trechos comuns (vêm de n8n/codigo/_comum.js) =====
const MODELO_CLAUDE = 'claude-opus-5-5';
// Se a API do Claude reclamar do campo "fallbacks", troque para false.
const USAR_FALLBACK = true;

// Mensagens fixas do Zé (não passam pela IA).
// Formatação do WhatsApp: *negrito*, _itálico_, linhas em branco entre blocos, poucos emojis com função.
const COMO_MANDAR =
  '📸 Manda a *foto* ou o *PDF* da receita\n' +
  '✍️ Ou *escreve* o nome do remédio\n' +
  '🎤 Ou manda um *áudio* falando o nome';
const MSG = {
  CONSENTIMENTO:
    'Oi! Eu sou o *Zé da Farma* 👋\n' +
    'Eu vejo se o remédio da sua receita é *de graça no Farmácia Popular* e onde retirar.\n\n' +
    '*Antes, um combinado rápido:*\n\n' +
    '🤝 Sou um projeto *voluntário*. *Não* sou canal oficial do governo.\n\n' +
    '🤖 A receita é lida por uma inteligência artificial (Claude, da Anthropic), só pra achar o nome do remédio. ' +
    'Áudio vira texto por outro serviço (Groq).\n\n' +
    '🔒 Não guardo foto, áudio, nome nem CPF. Guardo só um código no lugar do seu número, por até 24 horas.\n\n' +
    '🚫 Nunca peço senha nem dados de banco.\n\n' +
    '🗑️ Escreva *APAGAR* a qualquer hora e eu apago seus dados.\n\n' +
    'Pode ser? Escreva *SIM* pra continuar.',
  CONSENTIMENTO_NAO: 'Tudo bem! Não guardei nada. 👍\nSe mudar de ideia, é só mandar um *oi*.',
  BOAS_VINDAS: 'Oba! 🎉 Vamos lá:\n\n' + COMO_MANDAR + '\n\nQue eu vejo se tá na lista.\n\n💡 _Quer ver tudo o que é de graça? Escreva_ *LISTA*.',
  PEDIR_RECEITA: 'Oi, eu sou o *Zé da Farma*! 👋\n\n' + COMO_MANDAR + '\n\nQue eu vejo se tá na lista.',
  APAGADO: '🗑️ Pronto, *apaguei seus dados*.\nSe quiser usar de novo, é só mandar um *oi*.',
  RECOMECAR: '🔄 Beleza, vamos começar de novo.\n\n' + COMO_MANDAR,
  EXPIROU: '⏰ _Faz mais de um dia que a gente conversou, então comecei do zero._',
  FORA_CLINICO:
    '⚠️ *Essa eu não posso responder.*\n' +
    'Dose, efeito, troca ou mistura de remédios é com o *médico* ou o *farmacêutico*.\n\n' +
    'Eu só vejo se o remédio *tá na lista* do Farmácia Popular e *onde retirar*.',
  FORA_ESCOPO: 'Eu só sei falar do *Farmácia Popular* 🙂\n\n' + COMO_MANDAR + '\n\nQue eu vejo se tá na lista.',
  NUNCA_PEDIMOS:
    '🚨 *Atenção!*\n' +
    'Eu *nunca* peço senha, cartão, Pix ou dados de banco. Não mande isso aqui.\n\n' +
    'Se alguém pedir isso em nome do Farmácia Popular, *é golpe*.',
  NAO_PRECISA_CPF: '🔒 *Não precisa me mandar CPF* nem documento, e eu não guardo esses dados.\nO CPF você mostra só lá na farmácia.',
  AUDIO: '🎤 *Não consegui entender o áudio.*\nTenta gravar de novo, falando com calma.\n\n📸 Ou manda a foto da receita\n✍️ Ou escreve o nome do remédio',
  IMAGEM_GRANDE: '📦 *O arquivo ficou pesado demais pra mim.*\nTenta mandar uma *foto* ou um *print* da receita, ou escreve o nome do remédio.',
  IMAGEM_TIPO: '📄 *Não consegui abrir esse arquivo.*\nManda uma *foto* ou o *PDF* da receita, ou escreve o nome do remédio.',
  DICA_LISTA:
    '💊 Quer ver os remédios que saem *de graça* no Farmácia Popular?\n\n' +
    '👉 Escreva *LISTA* pra ver tudo\n' +
    '👉 Ou *LISTA PRESSÃO*, *LISTA DIABETES*… pra ver de uma doença',
  LISTA_VAZIA: 'Não achei remédio dessa doença na lista do Farmácia Popular. 🤔\n\n👉 Escreva *LISTA* pra ver tudo o que é de graça\n📸 Ou manda a foto da receita',
  NAO_LEGIVEL:
    '🔍 *Não consegui ler a receita direitinho.*\n\n' +
    'Tenta outra foto:\n• com *boa luz*\n• *bem de pertinho*\n• a receita *inteira* na foto\n\n✍️ Ou escreve o nome do remédio.',
  ERRO_TECNICO: '😕 Ops, tive um probleminha agora.\nTenta de novo daqui a pouco, ou escreve o nome do remédio.',
  CONFIRMACAO_NAO: 'Sem problema! 👍\n\n📸 Manda a foto de novo, bem de pertinho e com luz\n✍️ Ou escreve o *nome certo* do remédio',
  CONFIRMAR_DE_NOVO: 'Tá certo o que eu li?\n\n✅ Responda *SIM*\n✍️ Ou escreva o *nome certo* do remédio',
  PEDIR_CEP:
    '📍 *Agora me diz onde você está*, que eu mostro as farmácias mais perto:\n\n' +
    '• o *CEP* (só os números)\n• ou a *cidade e o bairro*\n\n_Pode ser por áudio também._ 🎤',
  CEP_INVALIDO:
    'Não entendi 🤔 Me manda:\n\n' +
    '• o *CEP* com 8 números (ex.: _01310100_)\n• ou a *cidade e o bairro* (ex.: _Vila Mariana, São Paulo_)',
  CEP_NAO_ACHADO: '📍 *Não achei esse CEP.*\nConfere e manda de novo (só os 8 números), ou escreve a *cidade e o bairro*.',
  CIDADE_NAO_ACHADA:
    '📍 *Não achei essa cidade* na lista do Farmácia Popular.\n\n' +
    '• Confere o nome da cidade\n• Ou manda o *CEP* (só os números)\n\n' +
    '_Se a cidade tem o mesmo nome em outro estado, escreva com o estado. Ex.: Santa Luzia PB._',
  SEM_CEP: 'Tudo bem! 👍\nProcure uma farmácia com a placa *"Aqui tem Farmácia Popular"*.\n\nSe precisar, é só mandar outra receita.',
  O_QUE_LEVAR:
    '🧾 *Pra retirar, leve:*\n' +
    '• Receita válida\n• Documento com foto\n• CPF\n\n' +
    '👥 Outra pessoa pode retirar por você, levando uma *procuração*.',
  INSUMO: '🩲 _Pra fralda geriátrica e absorvente, confirme na farmácia o que levar, porque as regras podem ser diferentes._',
  CONFIRA_ESTOQUE: '📞 Vale *confirmar na farmácia* se o remédio tá em estoque.\n\nPrecisa ver outra receita? É só mandar. 😉',
  NOME_FACHADA: 'ℹ️ _O nome na fachada pode ser diferente: procure a placa_ *"Aqui tem Farmácia Popular"*.',
  SEM_FARMACIA_PERTO:
    '📍 Pela lista oficial, *não achei farmácia* do Farmácia Popular nessa cidade.\n\n' +
    'Procure uma farmácia com a placa *"Aqui tem Farmácia Popular"* ou pergunte na *UBS* (posto de saúde).',
};

// Codifica em base64 para mandar ao Postgres sem problema com vírgulas e aspas
const b64 = (obj) => Buffer.from(JSON.stringify(obj ?? {}), 'utf8').toString('base64');

// Monta a saída padrão de cada ramo (vai para "Juntar resposta" -> "Salvar conversa")
function fim(d, o) {
  return {
    usuario_hash: d.usuario_hash,
    acao: o.acao || 'salvar',
    novo_estado: o.novo_estado || d.estado_atual || 'novo',
    novo_contexto_b64: b64(o.novo_contexto !== undefined ? o.novo_contexto : (d.contexto || {})),
    evento: o.evento || '-',
    detalhe_b64: b64({ ...(o.detalhe || {}), canal: d.canal }),
    resposta: o.resposta,
  };
}

// Lê a resposta da API do Claude com segurança
function lerRespostaClaude(r) {
  if (!r || r.error || r.type === 'error') return { ok: false, erro: 'api' };
  if (r.stop_reason === 'refusal') return { ok: false, erro: 'recusa' };
  if (r.stop_reason === 'max_tokens') return { ok: false, erro: 'max_tokens' };
  const texto = (r.content || []).filter(b => b.type === 'text').map(b => b.text).join('').trim();
  if (!texto) return { ok: false, erro: 'vazio' };
  return { ok: true, texto };
}

// Monta o corpo da chamada ao Claude
function corpoClaude(system, content, max_tokens, schema) {
  const corpo = {
    model: MODELO_CLAUDE,
    max_tokens,
    system,
    messages: [{ role: 'user', content }],
    output_config: { effort: 'low' },
  };
  if (schema) corpo.output_config.format = { type: 'json_schema', schema };
  if (USAR_FALLBACK) corpo.fallbacks = 'default';
  return corpo;
}

// Texto em MAIÚSCULAS, sem acento e sem pontuação (para comparar comandos)
const normCmd = (s) => (s || '').normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toUpperCase().replace(/[^A-Z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();

const cap = (s) => (s ? s.charAt(0).toUpperCase() + s.slice(1) : s);

// Resposta de reserva (sem IA) caso a redação do Claude falhe
function modeloResultado(fatos) {
  const blocos = fatos.itens.map((i) => {
    const nome = i.remedio_na_lista ? `*${cap(i.remedio_na_lista)}*` : `*O remédio nº ${i.numero}*`;
    const conc = i.concentracao_da_receita ? ' ' + i.concentracao_da_receita : '';
    const marca = i.marca ? `\n_${i.marca} é nome de marca; o genérico é ${i.remedio_na_lista}._` : '';
    switch (i.situacao) {
      case 'na_lista':
        return `✅ ${nome}${conc}${marca}\nTá na lista e é *de graça* no Farmácia Popular.`;
      case 'na_lista_sem_concentracao':
        return `✅ ${nome}${marca}\nTá na lista e é *de graça* em: ${(i.concentracoes_na_lista || []).join(', ')}.\nConfira se a da receita é uma dessas.`;
      case 'concentracao_fora_da_lista':
        return `❌ ${nome}${conc}${marca}\nNessa concentração *não* tá na lista. Procure a *UBS* (posto de saúde) ou a farmácia municipal.`;
      default:
        return `❌ ${nome}\n*Não* tá na lista. Procure a *UBS* (posto de saúde) ou a farmácia municipal.`;
    }
  });
  return blocos.join('\n\n'); // o próximo passo (pedir CEP/cidade) é colocado por "Conferir redação"
}
// ===== fim dos trechos comuns =====

// DECIDIR ROTA: olha o estado da conversa e a mensagem, e escolhe o caminho.
//   rota = 'fixa'      -> resposta pronta (sem IA)
//   rota = 'extrair'   -> ler receita/texto com o Claude
//   rota = 'resultado' -> pessoa confirmou: dizer se está na lista
//   rota = 'cep'       -> procurar farmácias pelo CEP
//   rota = 'cidade'    -> procurar farmácias pelo nome da cidade (e bairro)
//   rota = 'lista'     -> mostrar os remédios da lista oficial (tudo ou de uma doença)
const ent = $('Entrada → formato padrão').first().json;
const conv = $input.first().json.r;

const d = {
  canal: ent.canal,
  usuario_hash: conv.usuario_hash,
  estado_atual: conv.estado,
  contexto: conv.contexto || {},
  texto: ent.texto || '',
  imagem_base64: ent.imagem_base64,
  imagem_mime: ent.imagem_mime,
  imagem_bytes: ent.imagem_bytes || 0,
  aviso: conv.expirou ? MSG.EXPIROU + '\n\n' : '',
};

const t = normCmd(d.texto);
const temImagem = !!d.imagem_base64;
const fixa = (o) => [{ json: { ...fim(d, o), rota: 'fixa' } }];
const seguir = (rota, extra = {}) => [{ json: { ...d, rota, ...extra } }];

const MAX_IMG = 3.7 * 1024 * 1024; // limite do Claude é 5 MB em base64 (vale para foto e PDF)
const MIMES_OK = ['image/jpeg', 'image/png', 'image/webp', 'image/gif', 'application/pdf'];
const ehSim = ['SIM', 'S', 'ISSO', 'ISSO MESMO', 'CERTO', 'TA CERTO', 'ESTA CERTO', 'CORRETO', 'OK', 'CONFIRMO'].includes(t) || t.startsWith('SIM ');
const ehNao = ['NAO', 'N', 'ERRADO', 'TA ERRADO', 'ESTA ERRADO'].includes(t) || t.startsWith('NAO ');
const ehSaudacao = ['OI', 'OIE', 'OLA', 'BOM DIA', 'BOA TARDE', 'BOA NOITE', 'AJUDA', 'INICIO', 'OI ZE', 'OLA ZE', 'ZE'].includes(t);

// Perguntas clínicas e dados sensíveis: resposta fixa, sem IA, em qualquer estado
const RE_CLINICA = /(QUAL A DOSE|QUAL DOSE|QUE DOSE|DOSE CERTA|DOSAGEM|AUMENTAR A DOSE|DIMINUIR A DOSE|QUANTOS? (COMPRIMIDOS?|GOTAS|VEZES)|POSSO TOMAR|PODE TOMAR|DA PRA TOMAR|EFEITO|COLATERA|INTERACAO|INTERAGE|MISTURAR|TROCAR|SUBSTITU|ALCOOL|CERVEJA|BEBIDA|GRAVIDA|AMAMENTA|PARAR DE TOMAR|ESQUECI DE TOMAR|SERVE PRA|SERVE PARA|PRA QUE SERVE|PARA QUE SERVE|CONTRAINDICA|ALERGIA|FAZ MAL|REACAO)/;
const RE_SENSIVEL = /\b(SENHA|CARTAO(?! (DO )?SUS)|PIX|CONTA BANCARIA|CONTA DO BANCO|AGENCIA|CVV|TOKEN|BOLETO|DADOS BANCARIOS)\b/;
const RE_CPF = /\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/;

// Pergunta "quais remédios são de graça?": responde com a lista oficial (consulta ao banco, sem IA)
const RE_LISTA = new RegExp([
  '^LISTA( |$)',
  '\\b(QUAIS|QUE|QUAL)( SAO| E)?( OS| AS)? (REMEDIOS?|MEDICAMENTOS?)\\b.*\\b(GRACA|GRATIS|GRATUIT\\w*|LISTA|FARMACIA POPULAR|COBR\\w*|PEGAR|RETIRAR|TEM|DISTRIBU\\w*)\\b',
  '\\b(REMEDIOS|MEDICAMENTOS) (DE GRACA|GRATIS|GRATUITOS|COBERTOS|DA LISTA|DO PROGRAMA)\\b',
  '\\bO QUE (TEM|E|DA)( DE)? (GRACA|GRATIS)\\b',
  '\\bTEM (ALGUM )?(REMEDIO|MEDICAMENTO) (PRA|PARA|DE) ',
].join('|'));
// Filtro opcional por doença (o valor é um pedaço do nome da "indicação" na lista oficial)
const FILTROS_LISTA = [
  [/DIABET|GLICOSE|ACUCAR NO SANGUE|INSULINA/, 'DIABETES'],
  [/PRESSAO|HIPERTENS/, 'HIPERTENSAO'],
  [/ASMA|BRONQUITE|BOMBINHA/, 'ASMA'],
  [/RINITE/, 'RINITE'],
  [/COLESTEROL|DISLIPIDEMIA|TRIGLICER/, 'DISLIPIDEMIA'],
  [/PARKINSON/, 'PARKINSON'],
  [/GLAUCOMA/, 'GLAUCOMA'],
  [/OSTEOPOROSE/, 'OSTEOPOROSE'],
  [/ANTICONCEP|EVITAR GRAVIDEZ|PILULA/, 'ANTICONCEPCAO'],
  [/FRALDA|INCONTINENCIA/, 'INCONTINENCIA'],
  [/ABSORVENTE|MENSTRUA/, 'MENSTRUAL'],
];
const filtroLista = () => (FILTROS_LISTA.find(([re]) => re.test(t)) || [null, '-'])[1];

// CEP falado em palavras (áudio transcrito): "zero um três um zero um zero zero" -> 01310100.
// Só vale quando a mensagem é quase toda de números, para não confundir "um" de nomes de cidade.
const NUM_FALADO = { ZERO: '0', UM: '1', UMA: '1', DOIS: '2', DUAS: '2', TRES: '3', QUATRO: '4', CINCO: '5',
  SEIS: '6', MEIA: '6', SETE: '7', OITO: '8', NOVE: '9' };
function cepFalado(txt) {
  const pal = txt.split(' ').filter((p) => p && !['CEP', 'MEU', 'E', 'O', 'TRACO', 'HIFEN', 'PONTO'].includes(p));
  if (!pal.length) return null;
  const nums = pal.map((p) => (NUM_FALADO[p] !== undefined ? NUM_FALADO[p] : (/^\d+$/.test(p) ? p : null)));
  if (nums.some((x) => x === null)) return null;
  return nums.join('').split('');
}

function checarArquivo() {
  if (ent.tem_audio && !temImagem) return fixa({ resposta: MSG.AUDIO, evento: 'audio' });
  if (ent.outro_arquivo && !temImagem) return fixa({ resposta: MSG.IMAGEM_TIPO, evento: 'arquivo_invalido' });
  if (!temImagem) return null;
  if (!MIMES_OK.includes(d.imagem_mime)) return fixa({ resposta: MSG.IMAGEM_TIPO, evento: 'arquivo_invalido' });
  if (d.imagem_bytes > MAX_IMG) return fixa({ resposta: MSG.IMAGEM_GRANDE, evento: 'imagem_grande' });
  return null;
}

// 1) APAGAR vale em qualquer estado
if (t === 'APAGAR' || t === 'APAGAR MEUS DADOS') {
  return fixa({ resposta: MSG.APAGADO, acao: 'apagar', novo_estado: 'novo', novo_contexto: {}, evento: 'apagou' });
}

// 2) Consentimento: usuário novo só segue depois de responder SIM
if (d.estado_atual === 'novo') {
  const pedido = d.contexto.consentimento_pedido === true;
  if (pedido && (t === 'SIM' || t === 'S' || t.startsWith('SIM '))) {
    return fixa({ resposta: MSG.BOAS_VINDAS, acao: 'consentir', novo_estado: 'aguardando_receita', novo_contexto: {}, evento: 'consentiu' });
  }
