  else if (r.modo === 'bairro') {
    intro = porCidade
      ? `*Achei estas farmácias do Farmácia Popular nesse bairro, em ${cidadeUf}:*`
      : `*Achei estas farmácias do Farmácia Popular no seu bairro* (CEP ${cepFmt}):`;
