// Codifica em base64 para mandar ao Postgres sem problema com vírgulas e aspas
const b64 = (obj) => Buffer.from(JSON.stringify(obj ?? {}), 'utf8').toString('base64');

// Monta a saída padrão de cada ramo (vai para "Juntar resposta" -> "Salvar conversa")
function fim(d, o) {
  return {
    usuario_hash: d.usuario_hash,
    acao: o.acao || 'salvar',
    novo_estado: o.novo_estado || d.estado_atual || 'novo',
    novo_contexto_b64: b64(o.novo_contexto !== undefined ? o.novo_contexto : (d.contexto || {})),
    evento: o.evento || '-',
    detalhe_b64: b64({ ...(o.detalhe || {}), canal: d.canal }),
    resposta: o.resposta,
  };
}

// Lê a resposta da API do Claude com segurança
function lerRespostaClaude(r) {
  if (!r || r.error || r.type === 'error') return { ok: false, erro: 'api' };
  if (r.stop_reason === 'refusal') return { ok: false, erro: 'recusa' };
  if (r.stop_reason === 'max_tokens') return { ok: false, erro: 'max_tokens' };
  const texto = (r.content || []).filter(b => b.type === 'text').map(b => b.text).join('').trim();
  if (!texto) return { ok: false, erro: 'vazio' };
  return { ok: true, texto };
}

// Monta o corpo da chamada ao Claude
function corpoClaude(system, content, max_tokens, schema) {
  const corpo = {
    model: MODELO_CLAUDE,
    max_tokens,
    system,
    messages: [{ role: 'user', content }],
    output_config: { effort: 'low' },
  };
  if (schema) corpo.output_config.format = { type: 'json_schema', schema };
  if (USAR_FALLBACK) corpo.fallbacks = 'default';
  return corpo;
}

// Texto em MAIÚSCULAS, sem acento e sem pontuação (para comparar comandos)
const normCmd = (s) => (s || '').normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toUpperCase().replace(/[^A-Z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();

const cap = (s) => (s ? s.charAt(0).toUpperCase() + s.slice(1) : s);

// Resposta de reserva (sem IA) caso a redação do Claude falhe
function modeloResultado(fatos) {
  const blocos = fatos.itens.map((i) => {
    const nome = i.remedio_na_lista ? `*${cap(i.remedio_na_lista)}*` : `*O remédio nº ${i.numero}*`;
    const conc = i.concentracao_da_receita ? ' ' + i.concentracao_da_receita : '';
    const marca = i.marca ? `\n_${i.marca} é nome de marca; o genérico é ${i.remedio_na_lista}._` : '';
    switch (i.situacao) {
      case 'na_lista':
        return `✅ ${nome}${conc}${marca}\nTá na lista e é *de graça* no Farmácia Popular.`;
      case 'na_lista_sem_concentracao':
        return `✅ ${nome}${marca}\nTá na lista e é *de graça* em: ${(i.concentracoes_na_lista || []).join(', ')}.\nConfira se a da receita é uma dessas.`;
      case 'concentracao_fora_da_lista':
        return `❌ ${nome}${conc}${marca}\nNessa concentração *não* tá na lista. Procure a *UBS* (posto de saúde) ou a farmácia municipal.`;
      default:
        return `❌ ${nome}\n*Não* tá na lista. Procure a *UBS* (posto de saúde) ou a farmácia municipal.`;
    }
  });
  return blocos.join('\n\n'); // o próximo passo (pedir CEP/cidade) é colocado por "Conferir redação"
}
// ===== fim dos trechos comuns =====

// MONTAR LISTA: responde "quais remédios são de graça?" com a lista oficial que veio do banco.
// Sem IA: o texto é montado aqui, a partir da consulta "Listar remédios da lista oficial".
// Não muda o estado da conversa (a pessoa pode continuar de onde estava).
const d = $('Decidir rota').first().json;
const grupos = $input.first().json.r || [];

const NOMES = {
  'HIPERTENSAO': 'Pressão alta',
  'DIABETES': 'Diabetes',
  'DIABETES MELLITUS DOENCA CARDIOVASCULAR': 'Diabetes com doença do coração',
  'DISLIPIDEMIA': 'Colesterol',
  'ASMA': 'Asma',
  'RINITE': 'Rinite',
  'DOENCA DE PARKINSON': 'Parkinson',
  'GLAUCOMA': 'Glaucoma',
  'OSTEOPOROSE': 'Osteoporose',
  'ANTICONCEPCAO': 'Anticoncepcional',
  'INCONTINENCIA URINARIA': 'Incontinência urinária',
  'DIGNIDADE MENSTRUAL': 'Dignidade menstrual',
};
const ORDEM = Object.keys(NOMES); // pressão e diabetes primeiro (as mais comuns)
const rotulo = (ind) => NOMES[normCmd(ind)] || cap((ind || '').toLowerCase());
const posicao = (ind) => { const i = ORDEM.indexOf(normCmd(ind)); return i < 0 ? 99 : i; };
const conc = (c) => String(c)
  .replace(/(\d)\s*(mg|mcg|ml|ui|g)\b/gi, '$1 $2')
  .replace(/\bui\b/gi, 'UI').replace(/\bml\b/gi, 'mL')
  .replace(/\s*\(.*?\)/g, '');
grupos.sort((a, b) => posicao(a.indicacao) - posicao(b.indicacao));

if (!grupos.length) {
  return [{ json: fim(d, { resposta: MSG.LISTA_VAZIA, evento: 'pergunta_lista', detalhe: { filtro: d.filtro_lista } }) }];
}

const EMOJI = {
  'HIPERTENSAO': '❤️', 'DIABETES': '🩸', 'DIABETES MELLITUS DOENCA CARDIOVASCULAR': '💗', 'DISLIPIDEMIA': '🧪',
  'ASMA': '🫁', 'RINITE': '👃', 'DOENCA DE PARKINSON': '🧠', 'GLAUCOMA': '👁️', 'OSTEOPOROSE': '🦴',
  'ANTICONCEPCAO': '💊', 'INCONTINENCIA URINARIA': '🩲', 'DIGNIDADE MENSTRUAL': '🌸',
};
const blocos = grupos.map((g) => {
  const itens = (g.itens || []).map((i) => {
    const cs = [...new Set((i.concentracoes || []).map(conc))];
    return `• ${i.nome}${cs.length ? ` _(${cs.join(', ')})_` : ''}`;
  });
  return `${EMOJI[normCmd(g.indicacao)] || '💊'} *${rotulo(g.indicacao)}*\n${itens.join('\n')}`;
});

const todos = d.filtro_lista === '-';
const resposta =
  (todos
    ? '💊 *Remédios e itens DE GRAÇA no Farmácia Popular*\n_Lista oficial do Ministério da Saúde_\n\n'
    : '💊 *Da lista oficial do Farmácia Popular, estes saem DE GRAÇA:*\n\n') +
  blocos.join('\n\n') +
  '\n\n━━━━━━━━━━\n' +
  '👨‍⚕️ _Quem indica o remédio é o médico._\n\n' +
  (todos ? '🔎 Pra ver só de uma doença, escreva por exemplo: *LISTA DIABETES*\n' : '') +
  '📸 Manda a foto da receita que eu confiro se o seu tá na lista.';

return [{ json: fim(d, { resposta, evento: 'pergunta_lista', detalhe: { filtro: d.filtro_lista } }) }];
